import type { Metadata } from "next";
import { ComparisonTemplate } from "@/components/marketing/comparisontemplate/ComparisonTemplate";
import { COMPETITOR, FAQ } from "@/components/marketing/comparisontemplate/data";
import { CompetitorLogo } from "@/components/marketing/CompetitorLogo";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { FaqJsonLd, ProductJsonLd } from "@/components/marketing/StructuredData";
import { getVpsPriceBand } from "@/lib/vps-price-band";
import { db } from "@/lib/db";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
const PATH = "/preview/comparison";

/**
 * PREVIEW ROUTE — a template demonstration, not a live product page, so it stays
 * out of search (robots noindex). It still ships the complete SEO surface a real
 * comparison page would: full metadata (title/description/canonical/OG) plus
 * FAQ + Product/Offer JSON-LD, so the template can be judged as production-ready.
 */
export const metadata: Metadata = {
  title: "Nxeon vs DigitalOcean — an honest VPS comparison",
  description:
    "How Nxeon compares to DigitalOcean for cloud VPS hosting: pricing, NVMe storage, managed migration, support and where each one is the better fit — compared honestly, row by row.",
  alternates: { canonical: PATH },
  openGraph: {
    type: "article",
    title: "Nxeon vs DigitalOcean — an honest VPS comparison",
    description:
      "Pricing, NVMe storage, managed migration and support compared. An honest look at where each provider wins.",
    url: `${APP_URL}${PATH}`,
    images: [{ url: `${APP_URL}/logo.png` }],
  },
  // Preview surface — demonstrate the template without letting it rank.
  robots: { index: false, follow: false },
};

// Prices track the live catalogue — read the DB-fed band on every request.
export const dynamic = "force-dynamic";

export default async function Page() {
  // DB-fed Nxeon price band + plans, exactly like the live compare pages. Wrapped
  // so the preview degrades to neutral, price-free copy if the DB is unreachable.
  let fromLabel: string | undefined;
  let plans: Array<{ name: string; priceCents: number }> = [];
  try {
    const [band, planRows] = await Promise.all([
      getVpsPriceBand(),
      db.plan.findMany({
        where: { active: true },
        orderBy: { priceCents: "asc" },
        select: { name: true, priceCents: true },
      }),
    ]);
    fromLabel = band?.fromLabel;
    plans = planRows;
  } catch {
    /* DB unavailable — render the template without a price badge or Product schema */
  }

  return (
    <>
      <FaqJsonLd items={FAQ} />
      {plans.length > 0 ? <ProductJsonLd plans={plans} /> : null}
      <ComparisonTemplate
        nxeonLogo={<CompetitorLogo slug="nxeon" name="Nxeon" size={26} />}
        competitorLogo={<CompetitorLogo slug={COMPETITOR.slug} name={COMPETITOR.name} size={26} />}
        reviewBadges={<ReviewBadges />}
        fromLabel={fromLabel}
      />
    </>
  );
}
