62	/* ── self-contained motion hooks ─────────────────────────────────────────── */
63	function usePrefersReducedMotion() {
64	  const [reduced, setReduced] = useState(false);
65	  useEffect(() => {
66	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
67	    if (!mq) return;
68	    setReduced(mq.matches);
69	    const on = () => setReduced(mq.matches);
70	    mq.addEventListener?.("change", on);
71	    return () => mq.removeEventListener?.("change", on);
72	  }, []);
73	  return reduced;
74	}
75	
76	function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
77	  const ref = useRef<T | null>(null);
78	  const [seen, setSeen] = useState(false);
79	  useEffect(() => {
80	    const el = ref.current;
81	    if (!el || typeof IntersectionObserver === "undefined") {
82	      setSeen(true);
83	      return;
84	    }
85	    const io = new IntersectionObserver(
86	      ([e]) => {
87	        if (e.isIntersecting) {
88	          setSeen(true);
89	          io.disconnect();
90	        }
91	      },
92	      { threshold: 0.15, rootMargin: margin },
93	    );
94	    io.observe(el);
95	    return () => io.disconnect();
96	  }, [margin]);
97	  return { ref, seen };
98	}
99	
100	function useCountUp(target: number, active: boolean, duration = 1000, reduced = false) {
101	  const [val, setVal] = useState(reduced ? target : 0);
102	  useEffect(() => {
103	    if (!active) return;
104	    if (reduced) {
105	      setVal(target);
106	      return;
107	    }
108	    let raf = 0;
109	    const start = performance.now();
110	    const tick = (now: number) => {
111	      const t = Math.min(1, (now - start) / duration);
112	      const eased = 1 - Math.pow(1 - t, 3);
113	      setVal(Math.round(target * eased));
114	      if (t < 1) raf = requestAnimationFrame(tick);
115	    };
116	    raf = requestAnimationFrame(tick);
117	    return () => cancelAnimationFrame(raf);
118	  }, [target, active, duration, reduced]);
119	  return val;
120	}
