import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
import { APP_URL } from "@/components/marketing/StructuredData";
import {
  findCombo,
  buildLanding,
  findRegionCombo,
  buildRegionLanding,
  LANDING_SLUGS,
  REGION_LANDING_SLUGS,
  type LandingPlan,
} from "@/lib/marketing/locationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages, plus the
 * region-tier umbrella pages above them.
 *
 * One data-driven route renders the whole location × service matrix defined in
 * `lib/marketing/locationLandings.ts` — e.g. /london-vps-hosting,
 * /toronto-web-hosting, /frankfurt-game-server-hosting — AND the broader
 * region × service matrix above it — e.g. /usa-vps-hosting,
 * /europe-game-server-hosting — since both are built by the same data table
 * into the same `BuiltLanding` shape and render through the same
 * `UseCaseLanding` component. A slug is checked against the region matrix
 * first, then the city matrix; anything in neither falls through to a 404,
 * so this catch-all never shadows the hand-written marketing pages (which
 * win at request time anyway) or invents doorway pages. Real DB plans feed
 * the pricing grid and Product rich-result for both tiers.
 */

export const dynamic = "force-dynamic";

// Pre-declare the known slugs so Next can enumerate both matrices; unknown
// slugs are rejected in the page/metadata via notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS].map((slug) => ({ slug }));
}

async function loadPlans(): Promise<LandingPlan[]> {
  return db.plan.findMany({
    where: { active: true },
    orderBy: { sortOrder: "asc" },
  });
}

function resolveSlug(slug: string, plans: LandingPlan[]) {
  const regionCombo = findRegionCombo(slug);
  if (regionCombo) return buildRegionLanding(regionCombo, plans);
  const combo = findCombo(slug);
  if (combo) return buildLanding(combo, plans);
  return undefined;
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const plans = await loadPlans();
  const built = resolveSlug(slug, plans);
  if (!built) return {};

  const url = `${APP_URL}/${slug}`;

  return {
    title: built.metaTitle,
    description: built.metaDescription,
    alternates: { canonical: `/${slug}` },
    openGraph: {
      type: "article",
      title: built.ogTitle,
      description: built.ogDescription,
      url,
    },
    twitter: {
      card: "summary_large_image",
      title: built.ogTitle,
      description: built.ogDescription,
    },
  };
}

export default async function LocationServiceLandingPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const plans = await loadPlans();
  const built = resolveSlug(slug, plans);
  if (!built) notFound();

  const url = `${APP_URL}/${slug}`;

  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
  // the page's place in the site. FAQ + Product JSON-LD are emitted by
  // UseCaseLanding from the same content, so all three rich results are covered.
  const breadcrumb = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
    ],
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
      />
      <UseCaseLanding content={built.content} plans={plans} />
    </>
  );
}

