const FAQ = [
  {
    q: "Is this actually free, or a trial?",
    a: "Genuinely free — no credit card at signup, no expiry date. It's intentionally limited (1 GB RAM, sleeps when idle) so we can offer it to everyone; when you need more, upgrading to a dedicated paid server is one click away.",
  },
  {
    q: "Why does my server go to sleep?",
    a: "Free servers share a pool of resources. A server with nobody connected is stopped after a short idle period so that capacity is available for everyone else, and it starts back up automatically the moment someone connects — usually within about 15 seconds.",
