  },
  {
    q: "Why would you give away a Minecraft server for free?",
    a: "It's how we introduce people to Nxeon. Some players stay on the free tier forever, and that's genuinely fine — others outgrow it and upgrade to a paid game server. Either way, you got a real Minecraft server with no catch.",
  },
];

export default async function FreeMinecraftLandingPage() {
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");

  return (
    <>
      <FreeTierTemplate reviewBadges={<ReviewBadges />} domain={domain} />

      {/* ── Server directory ─────────────────────────────────────────────── */}
      <Section>
        <div className="mx-auto max-w-2xl text-center">
          <SectionTitle
            eyebrow="No friends with a server yet?"
            title="Browse public servers and jump in"
            sub="Owners can list their free server publicly — pick a world, grab the address, and play. No account needed to join."
          />
          <Link href="/servers" className="btn-secondary mt-6 inline-flex">
            Browse the server directory →
          </Link>
        </div>
      </Section>

      {/* ── FAQ ──────────────────────────────────────────────────────────── */}
      <Section tone="panel">
        <SectionTitle eyebrow="FAQ" title="Questions people actually ask" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {FAQ.map((f, i) => (
            <Reveal key={f.q} delay={i * 50} className="card">
              <h3 className="flex items-start gap-2.5 font-semibold text-[var(--fg)]">
                <IconCheck size={18} className="mt-0.5 shrink-0 text-brand-400" />
                {f.q}
              </h3>
              <p className="mt-2 pl-[26px] text-sm leading-relaxed text-[var(--fg-muted)]">{f.a}</p>
            </Reveal>
          ))}
        </div>
        <FaqJsonLd items={FAQ} />
        {/* Explicit $0 Offer — schema.org's normal way to mark a product genuinely
            free, distinct from ProductOffersJsonLd (StructuredData.tsx), which
            deliberately filters out zero-price offers so a REAL paid product
            never accidentally advertises $0. That guard doesn't apply here: $0
            is the actual, correct price for this one. */}
        <script
          type="application/ld+json"
          // eslint-disable-next-line react/no-danger
          dangerouslySetInnerHTML={{
            __html: JSON.stringify({
              "@context": "https://schema.org",
              "@type": "Product",
              name: "Nxeon Free Minecraft Server",
              description:
                "A free Minecraft server on its own subdomain — no credit card required, sleeps when idle, wakes on connect.",
              brand: { "@type": "Brand", name: "Nxeon" },
              offers: {
                "@type": "Offer",
                price: "0",
                priceCurrency: "USD",
                availability: "https://schema.org/InStock",
                url: `${APP_URL}/free-minecraft`,
              },
            }),
          }}
        />
      </Section>
    </>
  );
}

