    tier: "Game server",
    price: `$${(GAME_STARTER_PRICE_CENTS / 100).toFixed(2)}`,
    headline: "Minecraft server",
    meta: "From 1 GB · low ping",
    features: ["One-click game installs", "Full file + FTP access", "Singapore low-latency network", "Scheduled restarts"],
  });

  const priceFor = (cents: number) => cents / 100;

  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Singapore VPS & Game Servers"
        description="Cloud VPS and game servers deployed in the Singapore (SGP) region on enterprise NVMe, with always-on DDoS filtering and low-latency reach across Southeast Asia."
        url={`${APP_URL}/vps`}
        offers={locationPlans.map((p) => ({
