          price: p.id === "game-minecraft" ? priceFor(GAME_STARTER_PRICE_CENTS) : Number(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />
      <FaqJsonLd items={FAQ} />
      <LocationLanding reviewBadges={<ReviewBadges />} plans={locationPlans} />
    </>
  );
}

