import Link from "next/link";
import { useEffect, useState } from "react";
import styles from "./tool.module.css";
import { RELATED_TOOLS, HOW_STEPS, RECENT_CHECKS, SAMPLE_PLAYERS, TOOL_REVIEWS } from "./data";
import { usePrefersReducedMotion, useJitter } from "@/components/marketing/gamelanding/kit";
import { IconArrow, IconBolt, IconGame, IconGauge, IconUsers, IconServer, IconNetwork } from "@/components/marketing/icons";

type Status = "pinging" | "done";
type MockResult = {
  host: string;
  port: number;
  online: boolean;
  version: string;
  protocol: number;
  playersOnline: number;
  playersMax: number;
  motd: string;
  latency: number;
  sample: string[];
  history: number[];
};

function fnv(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h * 16777619) >>> 0;
  }
  return h;
}

function buildMock(host: string, port: number): MockResult {
  const h = fnv(host.toLowerCase() || "play.example.net");
  const players = 12 + (h % 340);
  const max = players < 80 ? 100 : players < 400 ? 500 : 1000;
  const latency = 8 + ((h >> 3) % 58);
  const history = Array.from({ length: 12 }, (_, i) => latency + (((h >> (i % 7)) % 12) - 6));
  return {
    host: host || "play.example.net",
    port: port || 25565,
    online: true,
    version: "1.21.1",
    protocol: 767,
    playersOnline: players,
    playersMax: max,
    motd: "A Nxeon-hosted server — welcome back, builder.",
    latency,
    sample: SAMPLE_PLAYERS.slice(0, 4),
    history: history.map((v) => Math.max(4, v)),
  };
}

