/* ── the tool ────────────────────────────────────────────────────────────── */
function McStatusTool() {
  const reduced = usePrefersReducedMotion();
  const [host, setHost] = useState("play.example.net");
  const [port, setPort] = useState("");
  const [status, setStatus] = useState<Status>(reduced ? "done" : "pinging");
  const [result, setResult] = useState<MockResult | null>(reduced ? buildMock("play.example.net", 25565) : null);
  const [runId, setRunId] = useState(0);

  function run(h: string, p: string) {
    const portNum = p.trim() ? Number(p) : 25565;
    if (reduced) {
      setResult(buildMock(h, portNum));
      setStatus("done");
      setRunId((n) => n + 1);
      return;
    }
    setStatus("pinging");
    setResult(null);
    const t = setTimeout(() => {
      setResult(buildMock(h, portNum));
      setStatus("done");
      setRunId((n) => n + 1);
    }, 950);
    return () => clearTimeout(t);
  }

  // Auto-run the demo once on mount.
  useEffect(() => {
    if (reduced) return;
    const cleanup = run("play.example.net", "");
    return cleanup;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  const players = useJitter(result?.playersOnline ?? 0, 4, status === "done", 2400, reduced);

  return (
    <div className="relative">
      <div className="pointer-events-none absolute -inset-[1.5px] rounded-[26px] bg-gradient-to-r from-accent-blue/40 via-brand-500/40 to-accent-cyan/40 opacity-70 blur-lg" aria-hidden />
      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: "radial-gradient(45% 45% at 15% 0%, rgba(59,130,246,0.16), transparent 70%), radial-gradient(45% 45% at 90% 100%, rgba(138,112,251,0.18), transparent 70%)" }}
          aria-hidden
        />
        {/* header */}
        <div className="flex items-center gap-2.5 border-b border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-gradient-to-br from-emerald-500/30 to-brand-500/30 text-emerald-200">
            <IconGame size={15} />
          </span>
          <span className="text-[13px] font-semibold text-white">Minecraft Server Status</span>
          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            live ping
          </span>
        </div>

        <div className="relative p-4 sm:p-5">
          {/* form */}
          <form
            onSubmit={(e) => {
              e.preventDefault();
              if (!host.trim()) return;
              run(host, port);
            }}
            className="flex flex-col gap-2.5 sm:flex-row sm:items-center"
          >
            <div className="flex flex-1 items-center gap-2 rounded-xl border border-white/10 bg-navy-950/70 px-3 transition-colors focus-within:border-brand-400/50">
              <span className="text-slate-500" aria-hidden>
                <IconServer size={15} />
              </span>
              <input
                value={host}
                onChange={(e) => setHost(e.target.value)}
                placeholder="play.example.net"
                spellCheck={false}
                autoCapitalize="off"
                autoCorrect="off"
                aria-label="Server address"
                className="min-w-0 flex-1 bg-transparent py-2.5 font-mono text-[14px] text-slate-100 outline-none placeholder:text-slate-600"
              />
            </div>
            <input
              value={port}
              onChange={(e) => setPort(e.target.value.replace(/[^0-9]/g, ""))}
              inputMode="numeric"
              placeholder="25565"
              aria-label="Port"
              className="w-full rounded-xl border border-white/10 bg-navy-950/70 px-3 py-2.5 font-mono text-[14px] text-slate-100 outline-none transition-colors placeholder:text-slate-600 focus:border-brand-400/50 sm:w-24"
            />
            <button type="submit" className="btn-deploy px-5 py-2.5 text-sm">
              Check status
            </button>
          </form>

          {/* result area */}
          <div className="relative mt-4 min-h-[236px]">
            {status === "pinging" && !reduced && (
              <div className="pointer-events-none absolute inset-x-0 top-0 z-10 overflow-hidden" aria-hidden>
                <span className={`block h-px w-full bg-gradient-to-r from-transparent via-accent-cyan/70 to-transparent ${styles.scan}`} />
              </div>
            )}

            {status === "pinging" ? (
              <div className="flex h-[236px] flex-col items-center justify-center gap-3 rounded-xl border border-dashed border-white/[0.08]">
                <span className={`flex items-center gap-1.5 ${styles.dots}`} aria-label="pinging">
                  <span className="h-2 w-2 rounded-full bg-brand-400" />
                  <span className="h-2 w-2 rounded-full bg-brand-400" />
                  <span className="h-2 w-2 rounded-full bg-brand-400" />
                </span>
                <p className="font-mono text-sm text-slate-400">Pinging {host || "play.example.net"}…</p>
              </div>
            ) : result ? (
              <div key={runId} className={styles.reveal}>
                {/* status header */}
                <div className="flex flex-wrap items-center gap-2.5">
                  <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/30 bg-emerald-500/10 px-3 py-1 text-sm font-semibold text-emerald-300">
                    <span className="h-2 w-2 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
                    {result.host}:{result.port} is ONLINE
                  </span>
                  <span className="rounded-full border border-brand-500/25 bg-brand-500/10 px-3 py-1 text-sm font-semibold text-brand-200 tabular-nums">
                    {players} / {result.playersMax} players
                  </span>
                </div>

                {/* MOTD */}
                <p className="mt-3 rounded-lg border border-white/[0.06] bg-navy-950/60 px-3 py-2 font-mono text-[13px] text-slate-300">
                  {result.motd}
                </p>

                {/* KV grid */}
                <div className="mt-3 grid gap-2 sm:grid-cols-2">
                  <KV icon={<IconGame size={14} />} k="Version" v={`${result.version} · protocol ${result.protocol}`} delay={60} />
                  <KV icon={<IconUsers size={14} />} k="Players online" v={`${players} of ${result.playersMax}`} delay={120} />
                  <KVLatency history={result.history} latency={result.latency} reduced={reduced} delay={180} />
                  <KV icon={<IconNetwork size={14} />} k="Edition" v="Java · SRV followed" delay={240} />
                </div>

                {/* online-now chips */}
                <div className="mt-3">
                  <p className="mb-1.5 text-[11px] font-medium uppercase tracking-wider text-slate-500">Online now</p>
                  <div className="flex flex-wrap gap-1.5">
                    {result.sample.map((p, i) => (
                      <span
                        key={p}
                        className={`inline-flex items-center gap-1.5 rounded-lg border border-white/[0.07] bg-white/[0.03] px-2.5 py-1 text-[12px] text-slate-300 ${styles.row}`}
                        style={{ animationDelay: `${260 + i * 60}ms` }}
                      >
                        <span className="h-4 w-4 rounded-sm bg-gradient-to-br from-accent-blue to-brand-500" />
                        {p}
                      </span>
                    ))}
                    <span className="inline-flex items-center rounded-lg border border-white/[0.07] bg-white/[0.03] px-2.5 py-1 text-[12px] text-slate-500">
                      +{Math.max(0, players - result.sample.length)} more
                    </span>
                  </div>
                </div>
              </div>
            ) : null}
          </div>

          <p className="mt-3 border-t border-white/[0.06] pt-3 text-[11px] text-slate-500">
            Preview shows a sample response. The live tool sends a real server-list ping — no login, nothing stored.
          </p>
        </div>
      </div>
    </div>
  );
}

function KV({ icon, k, v, delay }: { icon: React.ReactNode; k: string; v: string; delay: number }) {
  return (
    <div className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 ${styles.row}`} style={{ animationDelay: `${delay}ms` }}>
      <span className="text-brand-300">{icon}</span>
      <div className="min-w-0">
        <p className="text-[10px] uppercase tracking-wide text-slate-500">{k}</p>
        <p className="truncate font-mono text-[13px] text-white">{v}</p>
      </div>
    </div>
  );
}

function KVLatency({ history, latency, reduced, delay }: { history: number[]; latency: number; reduced: boolean; delay: number }) {
  const maxV = Math.max(...history, 1);
  return (
    <div className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 ${styles.row}`} style={{ animationDelay: `${delay}ms` }}>
      <span className="text-brand-300">
        <IconGauge size={14} />
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-[10px] uppercase tracking-wide text-slate-500">Latency</p>
        <div className="flex items-center gap-2">
          <p className="font-mono text-[13px] text-white">{latency} ms</p>
          <span className="flex h-4 flex-1 items-end gap-[2px]">
            {history.map((v, i) => (
              <span
                key={i}
                className={`w-full origin-bottom rounded-[1px] bg-gradient-to-t from-brand-500 to-accent-cyan ${reduced ? "" : "motion-safe:animate-grow-up"}`}
                style={{ height: `${Math.max(15, (v / maxV) * 100)}%`, animationDelay: `${i * 40}ms` }}
              />
            ))}
          </span>
        </div>
      </div>
    </div>
  );
}

