  const [error, setError] = useState("");
  const [runId, setRunId] = useState(0);

  async function run(h: string, p: string) {
    if (!h.trim()) return;
    setStatus("pinging");
    setResult(null);
    setError("");
    try {
      const res = await fetch("/api/tools/mc-status", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host: h, port: p.trim() ? Number(p) : undefined }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
      setStatus("done");
      setRunId((n) => n + 1);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
      setStatus("error");
    }
