                </p>
              </div>
            )}

            {status === "error" && (
              <div className="flex h-[160px] flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-rose-500/20 bg-rose-500/[0.03] text-center">
                <p className="text-sm font-medium text-rose-300">{error || "Check failed."}</p>
                <p className="max-w-xs text-[12px] text-slate-500">Double-check the address and port, then try again.</p>
              </div>
            )}

            {status === "done" && result && !result.online && (
              <div key={runId} className={styles.reveal}>
                <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/[0.04] px-3 py-1 text-sm font-semibold text-slate-300">
                  <span className="h-2 w-2 rounded-full bg-slate-500" />
                  {result.host}:{result.port} is OFFLINE
                </span>
                <p className="mt-3 max-w-sm text-[13px] leading-relaxed text-slate-500">
                  No response from that address/port. It may be down, firewalled, or the port could be wrong.
                </p>
              </div>
            )}

            {status === "done" && result && result.online && (
              <div key={runId} className={styles.reveal}>
                {/* status header */}
                <div className="flex flex-wrap items-center gap-2.5">
                  <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/30 bg-emerald-500/10 px-3 py-1 text-sm font-semibold text-emerald-300">
                    <span className="h-2 w-2 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
                    {result.host}:{result.port} is ONLINE
                  </span>
                  <span className="rounded-full border border-brand-500/25 bg-brand-500/10 px-3 py-1 text-sm font-semibold text-brand-200 tabular-nums">
                    {players} / {playersMax} players
                  </span>
                </div>

                {/* MOTD */}
                {result.motd && (
                  <p className="mt-3 rounded-lg border border-white/[0.06] bg-navy-950/60 px-3 py-2 font-mono text-[13px] text-slate-300">
                    {result.motd}
                  </p>
                )}

                {/* KV grid */}
                <div className="mt-3 grid gap-2 sm:grid-cols-2">
                  <KV icon={<IconGame size={14} />} k="Version" v={result.versionName ? `${result.versionName}${result.protocol ? ` · protocol ${result.protocol}` : ""}` : "Unknown"} delay={60} />
                  <KV icon={<IconUsers size={14} />} k="Players online" v={`${players} of ${playersMax}`} delay={120} />
                  <KV icon={<IconGauge size={14} />} k="Latency" v={typeof result.latencyMs === "number" ? `${result.latencyMs} ms` : "—"} delay={180} />
                  <KV icon={<IconNetwork size={14} />} k="Edition" v="Java · SRV followed" delay={240} />
                </div>

                {/* online-now chips — real sample names from the server's own status response */}
                {result.sample && result.sample.length > 0 && (
                  <div className="mt-3">
                    <p className="mb-1.5 text-[11px] font-medium uppercase tracking-wider text-slate-500">Online now</p>
                    <div className="flex flex-wrap gap-1.5">
                      {result.sample.map((p, i) => (
                        <span
                          key={p}
                          className={`inline-flex items-center gap-1.5 rounded-lg border border-white/[0.07] bg-white/[0.03] px-2.5 py-1 text-[12px] text-slate-300 ${styles.row}`}
                          style={{ animationDelay: `${260 + i * 60}ms` }}
                        >
                          <span className="h-4 w-4 rounded-sm bg-gradient-to-br from-accent-blue to-brand-500" />
                          {p}
                        </span>
                      ))}
                      {playersMax > 0 && players > result.sample.length && (
                        <span className="inline-flex items-center rounded-lg border border-white/[0.07] bg-white/[0.03] px-2.5 py-1 text-[12px] text-slate-500">
                          +{Math.max(0, players - result.sample.length)} more
                        </span>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          <p className="mt-3 border-t border-white/[0.06] pt-3 text-[11px] text-slate-500">
            A real Minecraft server-list ping — no login, nothing stored.
          </p>
        </div>
      </div>
    </div>
  );
}

function KV({ icon, k, v, delay }: { icon: React.ReactNode; k: string; v: string; delay: number }) {
  return (
    <div className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 ${styles.row}`} style={{ animationDelay: `${delay}ms` }}>
      <span className="text-brand-300">{icon}</span>
      <div className="min-w-0">
        <p className="text-[10px] uppercase tracking-wide text-slate-500">{k}</p>
        <p className="truncate font-mono text-[13px] text-white">{v}</p>
      </div>
    </div>
  );
}

