import type { Metadata } from "next";
import { ToolLanding } from "@/components/marketing/tooltemplate/ToolLanding";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { APP_URL } from "@/components/marketing/StructuredData";

const DESCRIPTION =
  "Free Minecraft server status checker — see if any Java Edition server is online, its player count, version, MOTD, and ping in one click. No login, nothing stored, SRV records followed automatically.";

export const metadata: Metadata = {
  title: "Minecraft Server Status Checker — Is My MC Server Online?",
  description: DESCRIPTION,
  alternates: { canonical: "/tools/minecraft-server-status" },
  openGraph: {
    type: "website",
    title: "Free Minecraft Server Status Checker",
    description: DESCRIPTION,
    url: `${APP_URL}/tools/minecraft-server-status`,
  },
};

// Tool-appropriate schema: a free, web-based utility. offers.price "0" marks it
// free; provider ties it to the Nxeon brand entity. Deliberately NOT paired
// with aggregateRating/review, since no genuine rating data exists for this tool.
const SOFTWARE_JSON_LD = {
  "@context": "https://schema.org",
  "@type": "SoftwareApplication",
  name: "Minecraft Server Status Checker",
  applicationCategory: "UtilitiesApplication",
  operatingSystem: "Any (web-based)",
  url: `${APP_URL}/tools/minecraft-server-status`,
  description: DESCRIPTION,
  featureList: [
    "Online/offline status",
    "Live player count",
    "Server version and protocol",
    "MOTD",
    "Latency / ping",
    "SRV record resolution",
  ],
  offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
  provider: { "@type": "Organization", name: "Nxeon", url: APP_URL },
};

const FAQ = [
  {
    q: "How do I check if a Minecraft server is online?",
    a: "Enter the server address (for example play.example.net) and, if it uses a non-standard port, that port too. We perform a real Minecraft Server List Ping and report whether the server responded, how many players are online, its MOTD and version, and the round-trip latency.",
  },
  {
    q: "What port do Minecraft servers use?",
    a: "Java Edition servers default to TCP port 25565. Leave the port blank to use it — we'll also follow a _minecraft._tcp SRV record if the domain publishes one, which is how many servers map a bare domain to a different port.",
  },
  {
    q: "Why does my server show as offline when it's running?",
    a: "The check runs from the public internet. A server can be up locally yet unreachable because of a firewall, a missing port-forward, an SRV/DNS record pointing elsewhere, or the wrong port. If it works on your LAN but shows offline here, those layers are the usual cause.",
  },
  {
    q: "Does this work for Bedrock servers?",
    a: "This tool speaks the Java Edition Server List Ping protocol. Bedrock uses a different (UDP) query protocol, so Bedrock-only servers won't respond here.",
  },
  {
    q: "What is the MOTD?",
    a: "The Message of the Day — the description line a server shows in the multiplayer list. We parse it out of the status response, including servers that send it as a formatted chat component.",
  },
];

export default function Page() {
  return (
    <>
      <script
        type="application/ld+json"
        // JSON.stringify output is safe to inline; no user input here.
        dangerouslySetInnerHTML={{ __html: JSON.stringify(SOFTWARE_JSON_LD) }}
      />
      <ToolLanding reviewBadges={<ReviewBadges />} />

      {/* ── ABOUT / SEO PROSE ────────────────────────────────────────────── */}
      <Section tone="panel">
        <div className="mx-auto max-w-3xl space-y-10">
          <div>
            <h2 className="text-xl font-semibold text-white sm:text-2xl">
              What does this Minecraft server status checker do?
            </h2>
            <p className="mt-3 text-[15px] leading-relaxed text-slate-400">
              It performs a real <b className="text-slate-200">Minecraft Server List Ping</b> — the same
              handshake your game client uses when it shows a server in the multiplayer list. We open a TCP
              connection, send the status request, and read back the server&apos;s live status: online/offline,
              players online and max, the MOTD, the version string, and the round-trip latency. No mod or login
              is needed, and the check runs from our servers so it reflects what players on the public internet
              actually see.
            </p>
          </div>
          <div>
            <h2 className="text-xl font-semibold text-white sm:text-2xl">Address, port and SRV records</h2>
            <ul className="mt-3 list-disc space-y-1.5 pl-5 text-[15px] leading-relaxed text-slate-400">
              <li>
                Java Edition servers listen on TCP <b className="text-slate-200">25565</b> by default — leave the
                port blank to use it.
              </li>
              <li>
                Many servers map a plain domain to a different port with a{" "}
                <b className="text-slate-200">_minecraft._tcp</b> SRV record; we follow it automatically when you
                don&apos;t set a port.
              </li>
              <li>A specific port you enter always wins over the SRV record.</li>
            </ul>
          </div>
        </div>
      </Section>

      {/* ── FAQ ──────────────────────────────────────────────────────────── */}
      <Section tone="base">
        <SectionTitle eyebrow="FAQ" title="Frequently asked questions" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify({
              "@context": "https://schema.org",
              "@type": "FAQPage",
              mainEntity: FAQ.map((f) => ({
                "@type": "Question",
                name: f.q,
                acceptedAnswer: { "@type": "Answer", text: f.a },
              })),
            }),
          }}
        />
      </Section>
    </>
  );
}
